<?php
declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('contract_templates.manage');
$id=max(0,(int)($_GET['id']??$_POST['id']??0));$template=null;if($id){$stmt=db()->prepare('SELECT * FROM contract_templates WHERE id=?');$stmt->execute([$id]);$template=$stmt->fetch();if(!$template){http_response_code(404);exit('Plantilla no encontrada.');}}
$pageTitle=$template?'Editar plantilla':'Nueva plantilla';$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim((string)($_POST['name']??''));$language=(string)($_POST['language']??'es');$title=trim((string)($_POST['title']??''));$content=trim((string)($_POST['content']??''));$sort=max(0,(int)($_POST['sort_order']??0));$active=isset($_POST['is_active'])?1:0;if(!in_array($language,['es','pt','en'],true))$language='es';if($name==='')$errors[]='El nombre es obligatorio.';if($title==='')$errors[]='El título es obligatorio.';if(strlen($content)<30)$errors[]='El contenido debe tener al menos 30 caracteres.';if(!$errors){if($id)db()->prepare('UPDATE contract_templates SET name=?,language=?,title=?,content=?,sort_order=?,is_active=? WHERE id=?')->execute([$name,$language,$title,$content,$sort,$active,$id]);else db()->prepare('INSERT INTO contract_templates(name,language,title,content,sort_order,is_active) VALUES (?,?,?,?,?,?)')->execute([$name,$language,$title,$content,$sort,$active]);flash('success',$id?'Plantilla actualizada.':'Plantilla creada.');redirect('contract_templates.php');}}
$v=fn(string$key,mixed$default='')=>$_POST[$key]??($template[$key]??$default);require __DIR__.'/includes/header.php';?>
<?php foreach($errors as$error):?><div class="alert alert-error"><?=e($error)?></div><?php endforeach;?><form method="post" class="panel"><div class="panel-header"><div><h2><?=$template?'Actualizar plantilla':'Crear modelo de contrato'?></h2><span class="table-sub">Puedes usar variables como {{CLIENTE}}, {{ID_CLIENTE}}, {{SERVICIOS}}, {{VALOR}} y {{FECHA_INICIO}}.</span></div><a class="btn btn-light btn-small" href="contract_templates.php">Cancelar</a></div><div class="panel-body form-grid"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><label>Nombre interno *<input name="name" required value="<?=e($v('name'))?>"></label><label>Idioma<select name="language"><option value="es" <?=$v('language','es')==='es'?'selected':''?>>Español</option><option value="pt" <?=$v('language')==='pt'?'selected':''?>>Português</option><option value="en" <?=$v('language')==='en'?'selected':''?>>English</option></select></label><label>Orden<input type="number" min="0" name="sort_order" value="<?=e($v('sort_order',0))?>"></label><label class="full">Título del contrato *<input name="title" required value="<?=e($v('title'))?>"></label><label class="full">Contenido editable *<textarea name="content" rows="22" required><?=e($v('content'))?></textarea></label><label class="checkbox-row"><input type="checkbox" name="is_active" value="1" <?=((int)$v('is_active',1)===1)?'checked':''?>> Plantilla activa</label><div class="full form-actions"><a class="btn btn-light" href="contract_templates.php">Cancelar</a><button class="btn btn-primary">GUARDAR PLANTILLA</button></div></div></form><?php require __DIR__.'/includes/footer.php';?>
